// Format pending orders
const orders = items;

if (orders.length === 0) {
  return [{
    json: {
      message: "📭 No pending orders"
    }
  }];
}

let message = "🎁 **Pending Orders**\n\n";
let totalValue = 0;

for (const order of orders) {
  const orderDate = new Date(order.json.order_date).toLocaleDateString();
  const daysAgo = Math.floor((new Date() - new Date(order.json.order_date)) / (1000 * 60 * 60 * 24));

  message += `**Order #${order.json.id}**\n`;
  message += `📅 ${orderDate} (${daysAgo} days ago)\n`;
  message += `👤 ${order.json.customer_name}\n`;
  message += `📦 ${order.json.product_type}: ${order.json.custom_text || order.json.description}\n`;
  message += `💰 £${order.json.price}\n`;
  if (order.json.deadline) {
    const deadline = new Date(order.json.deadline).toLocaleDateString();
    message += `⏰ Deadline: ${deadline}\n`;
  }
  message += `\n`;

  totalValue += parseFloat(order.json.price || 0);
}

message += `\n💵 **Total Value:** £${totalValue.toFixed(2)}`;

return [{
  json: {
    message: message,
    order_count: orders.length,
    total_value: totalValue
  }
}];

// Format in-production orders
const orders = items;

if (orders.length === 0) {
  return [{
    json: {
      message: "📭 No orders in production"
    }
  }];
}

let message = "🔨 **Orders In Production**\n\n";

for (const order of orders) {
  const startDate = new Date(order.json.production_started_at).toLocaleDateString();
  const daysInProd = Math.floor((new Date() - new Date(order.json.production_started_at)) / (1000 * 60 * 60 * 24));

  message += `**Order #${order.json.id}**\n`;
  message += `👤 ${order.json.customer_name}\n`;
  message += `📦 ${order.json.product_type}\n`;
  message += `🔨 Started: ${startDate} (${daysInProd} days)\n`;
  message += `💰 £${order.json.price}\n`;

  if (order.json.deadline) {
    const deadline = new Date(order.json.deadline);
    const daysUntil = Math.ceil((deadline - new Date()) / (1000 * 60 * 60 * 24));
    const deadlineStr = deadline.toLocaleDateString();
    const urgency = daysUntil <= 2 ? '🔴' : daysUntil <= 5 ? '🟡' : '🟢';
    message += `${urgency} Deadline: ${deadlineStr} (${daysUntil} days)\n`;
  }
  message += `\n`;
}

return [{
  json: {
    message: message,
    order_count: orders.length
  }
}];

// Parse new order details
const input = items[0].json.message.text;
const lines = input.split('\n').map(l => l.trim()).filter(l => l);

if (lines.length < 9) {
  return [{
    json: {
      error: true,
      message: "❌ Missing information. Please provide all 9 items."
    }
  }];
}

return [{
  json: {
    error: false,
    customer_name: lines[0],
    customer_email: lines[1],
    customer_phone: lines[2],
    product_type: lines[3],
    description: lines[4],
    custom_text: lines[4],
    material: lines[5],
    size: lines[6],
    price: parseFloat(lines[7]),
    deadline: lines[8],
    status: 'pending',
    order_date: new Date().toISOString().split('T')[0]
  }
}];

