// Format analytics
const data = items;

if (data.length === 0) {
  return [{
    json: {
      message: "📭 No orders in the last 30 days"
    }
  }];
}

let message = "📊 **Woody's Creations Analytics (30 Days)**\n\n";
let totalRevenue = 0;
let totalOrders = 0;

for (const item of data) {
  const count = item.json.count;
  const revenue = parseFloat(item.json.revenue || 0);
  const avgPrice = parseFloat(item.json.avg_price || 0);

  message += `**${item.json.product_type}**\n`;
  message += `📦 Orders: ${count}\n`;
  message += `💰 Revenue: £${revenue.toFixed(2)}\n`;
  message += `📊 Avg Price: £${avgPrice.toFixed(2)}\n`;
  message += `\n`;

  totalRevenue += revenue;
  totalOrders += count;
}

message += `\n**TOTALS**\n`;
message += `📦 Total Orders: ${totalOrders}\n`;
message += `💵 Total Revenue: £${totalRevenue.toFixed(2)}\n`;
message += `📊 Average Order: £${(totalRevenue / totalOrders).toFixed(2)}`;

return [{
  json: {
    message: message,
    total_orders: totalOrders,
    total_revenue: totalRevenue
  }
}];
